    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []

    for token in it:
        n = int(token)
        if n == 0:
            break

        stack = []          # each element: [color, length]
        for i in range(1, n + 1):
            c = int(next(it))

            if i & 1:       # i is odd
                if stack and stack[-1][0] == c:
                    stack[-1][1] += 1
                else:
                    stack.append([c, 1])
            else:           # i is even
                if stack and stack[-1][0] == c:
                    stack[-1][1] += 1
                else:
                    k = stack.pop()[1]   # length of the removed group
                    total = k + 1        # stones that will appear in the new colour
                    if stack and stack[-1][0] == c:
                        stack[-1][1] += total
                    else:
                        stack.append([c, total])

        # count white stones (color 0)
        white = sum(length for col, length in stack if col == 0)
        out_lines.append(str(white))

    sys.stdout.write("\n".join(out_lines))


