import sys
import bisect

def build_sparse(arr):
    n = len(arr)
    log = [0] * (n + 1)
    for i in range(2, n + 1):
        log[i] = log[i // 2] + 1
    k = log[n] + 1
    st = [arr]
    j = 1
    while (1 << j) <= n:
        step = 1 << (j - 1)
        prev = st[-1]
        cur = [max(prev[i], prev[i + step]) for i in range(n - (1 << j) + 1)]
        st.append(cur)
        j += 1
    return st, log

def query_sparse(st, log, l, r):
    k = log[r - l + 1]
    return max(st[k][l], st[k][r - (1 << k) + 1])

def solve() -> None:
