            s = int(next(it))
            heroes.append((p, s))
            if p > max_hero_power:
                max_hero_power = p

        max_a = max(a)
        if max_hero_power < max_a:
            out_lines.append("-1")
            continue

        # ----- build best array -----
        # collect all distinct power values
        vals_set = set(a)
        for p, _ in heroes:
            vals_set.add(p)
        vals = sorted(vals_set)
        sz = len(vals)

        exact = {}
        for p, s in heroes:
            if p not in exact or s > exact[p]:
                exact[p] = s

        best_arr = [0] * sz
        for i, v in enumerate(vals):
            if v in exact:
                best_arr[i] = exact[v]
        for i in range(sz - 2, -1, -1):
            if best_arr[i] < best_arr[i + 1]:
                best_arr[i] = best_arr[i + 1]

        def best_query(val: int) -> int:
            idx = bisect.bisect_left(vals, val)
            if idx >= sz:
                return 0
            return best_arr[idx]

        # ----- sparse table for range max -----
        st, log_table = build_sparse(a)

        def seg_query(l, r):
            return query_sparse(st, log_table, l, r)

        # ----- two-pointer to compute reach[i] -----
        reach = [0] * n
        l = 0
        r = 0
        while l < n:
            if r < l:
                r = l
            while r < n:
                mx = seg_query(l, r)
                length = r - l + 1
                if length <= best_query(mx):
                    r += 1
                else:
                    break
            reach[l] = r - 1
            l += 1

        # ----- greedy walk -----
        days = 0
        cur = 0
        while cur < n:
            nxt = reach[cur] + 1
            if nxt <= cur:
                days = -1
                break
            cur = nxt
            days += 1
        out_lines.append(str(days))

    sys.stdout.write("\n".join(out_lines))

