import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    n = int(next(it))
    groups = []          # list of lists of (weight, value) for coasters with b>0
    unbounded = []       # list of (value, weight) for coasters with b=0

    for _ in range(n):
        a = int(next(it))
        b = int(next(it))
        t = int(next(it))

        if b == 0:
            if a > 0:
                unbounded.append((a, t))
        else:
            opts = []
            total = 0
            k = 1
            while True:
                fun = a - (k - 1) * (k - 1) * b
                if fun <= 0:
                    break
                total += fun
                w = k * t
                # weight larger than 25000 is useless (max T)
                if w <= 25000:
                    opts.append((w, total))
                k += 1
            if opts:
                groups.append(opts)

    q = int(next(it))
    queries = [int(next(it)) for _ in range(q)]
    if not queries:
        return
    maxT = max(queries)

    dp = [0] * (maxT + 1)

    # ----- process groups (multiple choice knapsack) -----
    for opts in groups:
        newdp = dp[:]                     # copy current state
        for w, v in opts:
            if w > maxT:
                continue
            # classic 0/1 knapsack update, but using the OLD dp
            for j in range(maxT, w - 1, -1):
                cand = dp[j - w] + v
                if cand > newdp[j]:
                    newdp[j] = cand
        dp = newdp

    # ----- process unbounded items (complete knapsack) -----
    for v, w in unbounded:
        if w > maxT:
            continue
        for j in range(w, maxT + 1):
            cand = dp[j - w] + v
            if cand > dp[j]:
                dp[j] = cand

    # prefix max: we may leave earlier
    for i in range(1, maxT + 1):
        if dp[i] < dp[i - 1]:
            dp[i] = dp[i - 1]

    out_lines = [str(dp[t]) for t in queries]
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

